import{z as i,x as o,o as B,c as d,q as A,j as n,D as l,d as e,s as t,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"长上下文评测服务化","description":"","frontmatter":{"title":"长上下文评测服务化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lc-eval-serving.md","filePath":"llm/lc-eval-serving.md","lastUpdated":1791413859000}'),m={name:"llm/lc-eval-serving.md"};function h(p,E,D,c,F,f){const r=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="长上下文评测服务化" tabindex="-1">长上下文评测服务化 <a class="header-anchor" href="#长上下文评测服务化" aria-label="Permalink to &quot;长上下文评测服务化&quot;">​</a></h1><div class="epigraph"><p>长上下文的分数不只属于模型，也属于 serving 的每一枚旋钮；不钉旋钮的评测，测的是一次偶然的部署。</p><footer>—— 据 Hsieh et al., RULER, 2024 与 lm-evaluation-harness 的版本绑定口径整理</footer></div><p><a href="/llm/lc-multidoc-workload">上一课</a>立起多文档的共享结构，「服务语义」单元的行为契约到此讲完。「工程化」单元从本课起，把这些契约变成可发布的门槛。质量测法已有三件套——<a href="/llm/niah">针测</a>、<a href="/llm/long-context-eval">有效窗口曲线</a>、<a href="/llm/longbench-ruler">LongBench / RULER / ∞Bench</a>；<a href="/llm/eval-harness">评测框架课</a>立过「分数绑定框架版本」。本课补长上下文特有的一条：分数还绑定服务配置，评测必须当成负载工程来做。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一份权重，在不同服务配置下是不同的被测对象。KV 量化降档、驱逐策略、外推表版本、采样参数，都能把分数移动到与模型代差同级的幅度；而块长、缓存、分离式部署不改分数，却把评测的时延与成本改变数倍。两组旋钮不分开钉，比较就无效。长上下文还让评测本身变贵：一张 16×16 的针测网格是 256 条 128K 的 prefill，当普通脚本跑，账会先于结论爆炸。最后是缓存的新干扰：跨题命中能把时延压低，也会让「实现差异」混进「模型差异」——两个引擎跑同一模型，一个开着自动前缀共享、一个关着，分数与耗时都不可比。</p><p><span class="marginnote">直觉类比：把质量旋钮想成「改考卷内容」，时延旋钮想成「改考场时钟」。KV 精度、外推表动了，考生看到的题就变了，分数没法归因给模型；块长、批大小、拓扑动了，题没变，只是考试办得快慢不同，动的是成本与时延。两组旋钮混在一张成绩单里，等于既改了考卷又换了钟表，还问「这次为什么考砸」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>评测服务化三个动作。协议钉两组旋钮：质量侧（KV 精度、驱逐策略、外推版本、采样与长度预算）写进报告，时延侧（块长、缓存命中口径、批大小、部署拓扑）写进负载说明——<a href="/llm/eval-variance-seed">评测方差课</a>的随机维 \\(\\xi\\) 在这里多出服务维，报告格式沿<a href="/llm/eval-harness">框架课</a>的「版本三元组」扩成四元组。门禁化：把有效长度曲线与针测热力图做成发版门禁，任何触碰质量旋钮的变更必须重跑对应任务族——按失效模式的局部性抽样：精度降档主要伤针测召回，外推换版主要伤远距离任务，全量重跑买不来归因，只会拖到没人等得起。评测当负载：用评测集的长度分布编预算（<a href="/llm/lc-memory-account">显存账课</a>的账），网格与真实长任务按成本分层抽样；时延验收用分位数，与<a href="/llm/lc-longoutput-streaming">流式课</a>的契约同一口径。缓存口径：质量评测关跨题缓存或钉隔离，模型比较才干净；时延评测反过来，必须开缓存测真实部署的命中率。</p><p><span class="marginnote">数字实例：「四元组」长什么样？一行报告头形如 <code>(harness v0.4.3, RULER-niah-16x16, base=模型 sha:9f3e2a, serving=kv:fp16/evict:lru/block:512/cache:off/temp:0)</code>——复制这一行，别人才能在数月后复现同一个被测对象。少了 serving 那一节，两个分数之间的差异就有相当概率只是配置漂移。</span></p>',9)),(B(),n(s,null,{default:l(()=>[t(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHG%5B%22%E9%85%8D%E7%BD%AE%E5%8F%98%E6%9B%B4%EF%BC%9A%E7%B2%BE%E5%BA%A6%20%2F%20%E5%A4%96%E6%8E%A8%E8%A1%A8%20%2F%20%E9%A9%B1%E9%80%90%20%2F%20%E5%9D%97%E9%95%BF%22%5D%20--%3E%20WHO%7B%22%E5%8A%A8%E4%BA%86%E5%93%AA%E7%BB%84%E6%97%8B%E9%92%AE%3F%22%7D%0A%20%20WHO%20--%3E%7C%E8%B4%A8%E9%87%8F%E6%97%8B%E9%92%AE%7C%20QGATE%5B%22%E9%87%8D%E8%B7%91%E5%AF%B9%E5%BA%94%E4%BB%BB%E5%8A%A1%E6%97%8F%EF%BC%9A%E9%92%88%E6%B5%8B%20%2B%20%E6%9C%89%E6%95%88%E9%95%BF%E5%BA%A6%22%5D%0A%20%20WHO%20--%3E%7C%E6%97%B6%E5%BB%B6%E6%97%8B%E9%92%AE%7C%20LGATE%5B%22%E9%87%8D%E8%B7%91%E8%B4%9F%E8%BD%BD%E7%94%BB%E5%83%8F%EF%BC%9A%E5%88%86%E4%BD%8D%E6%95%B0%E6%97%B6%E5%BB%B6%20%2B%20%E5%91%BD%E4%B8%AD%E7%8E%87%22%5D%0A%20%20QGATE%20--%3E%20REL%5B%22%E6%94%BE%E8%A1%8C%EF%BC%9A%E7%89%88%E6%9C%AC%E4%B8%8E%E6%97%8B%E9%92%AE%E5%86%99%E8%BF%9B%E6%8A%A5%E5%91%8A%22%5D%0A%20%20LGATE%20--%3E%20REL%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("质量旋钮为什么必须进协议：KV 量化与驱逐改变的是模型可见的证据集，外推表改变的是位置语义——它们不是「工程细节」，是推理时模型定义的一部分。分数一移动，归因就断：两个不钉旋钮的分数之间，你不知道差的是模型还是部署。门禁按任务族抽样的依据是失效的局部性：每种质量旋钮只伤一个任务族，抽对了既省钱又保留归因；抽样表本身要随旋钮类型版本化。在线影子评测补最后一块：排队效应、真实命中率、"),a("a",{href:"/llm/lc-longoutput-streaming"},"长输出的分位尾部"),e("，评测集测不了，只能用真实流量旁路测——离线门禁管「对不对」，影子测量管「疼不疼」。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"评测自身的账：256 条 128K 提示约 3300 万 token 的 prefill，8B 模型约 \\(5\\times10^{17}\\) FLOPs——单卡按小时计，八卡节点按分钟计。这就是门禁必须按任务族抽样、评测集必须按长度分层的原因。")],-1)),(B(),n(s,null,{default:l(()=>[t(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E8%B7%91%E4%B8%80%E8%BD%AE%E8%AF%84%E6%B5%8B%22%5D%20--%3E%20Q%7B%22%E7%9B%AE%E7%9A%84%E6%98%AF%E6%AF%94%E6%A8%A1%E5%9E%8B%E8%B4%A8%E9%87%8F%3F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20OFF%5B%22%E7%BC%93%E5%AD%98%3A%E5%85%B3%E6%88%96%E9%9A%94%E7%A6%BB%22%5D%0A%20%20OFF%20--%3E%20QO%5B%22%E5%88%86%E6%95%B0%E5%8F%AA%E5%8F%8D%E6%98%A0%E6%A8%A1%E5%9E%8B%E5%B7%AE%E5%BC%82%22%5D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20GOFF%5B%22%E9%87%8D%E8%B7%91%E5%8F%97%E5%BD%B1%E5%93%8D%E4%BB%BB%E5%8A%A1%E6%97%8F%E9%97%A8%E7%A6%81%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%2C%E6%B5%8B%E6%97%B6%E5%BB%B6%7C%20ON%5B%22%E7%BC%93%E5%AD%98%3A%E5%BC%80%2C%E9%92%89%E5%91%BD%E4%B8%AD%E5%8F%A3%E5%BE%84%22%5D%0A%20%20ON%20--%3E%20TO%5B%22%E6%97%B6%E5%BB%B6%E5%8F%8D%E6%98%A0%E7%9C%9F%E5%AE%9E%E9%83%A8%E7%BD%B2%2C%E5%90%AB%E5%91%BD%E4%B8%AD%22%5D%0A%20%20Q%20--%3E%7C%E5%90%A6%2C%E6%B5%8B%E6%97%B6%E5%BB%B6%7C%20PCTL%5B%22%E6%8A%A5%E5%88%86%E4%BD%8D%E6%95%B0%3AP50%2FP99%20%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">常见误区：「把缓存开着跑质量评测，反正跑得快」。跨题共享的长前缀一旦命中，不同题的耗时互相耦合，你测到的「引擎 A 比引擎 B 快」可能只是 A 的缓存策略更激进——而分数本身也可能因预热顺序不同而抖动。模型比较要先关缓存把变量钉死，时延画像再单独开缓存测真实命中率。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各基准的构造与解释是三件套课的事，本课不重述；在线影子测量测不了长尾任务质量，离线门禁测不了排队——两者互补不可互替。评测温度与解码协议的纪律照<a href="/llm/eval-variance-seed">方差课</a>，本课只加服务维。最后一条纪律：服务配置的任何「临时调优」若出现在评测里而没出现在报告里，评测作废——这条比任何统计方法都更常救场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长上下文分数绑定服务配置：质量旋钮改变被测对象，时延旋钮改变评测成本，两组分开钉。</li><li>报告从版本三元组扩成四元组：框架、任务、适配器之外，加服务配置。</li><li>门禁按失效局部性抽样：精度伤召回、外推伤远距离，抽对了省钱又保归因。</li><li>缓存双口径：质量评测关缓存保纯净，时延评测开缓存测真实命中。</li><li>出处：Hsieh et al., RULER（2024）；Zhang et al., ∞Bench（2024）；lm-evaluation-harness 的版本绑定口径。</li></ul>',5))])}const v=i(m,[["render",h]]);export{u as __pageData,v as default};
